-- 0092_template_photo_fixes.sql (storefront templates 49–100, 2026-10-21)
--
-- Two photos in templates seeded by 0090 broke the no-people photo rule:
--   koora: the team-kit jersey photo (a printed player name) → folded blank team shirts.
--   sabaha: the beach towel photo (its print shows small cartoon swimmers) → a striped towel.
-- Both photos are only in the gallery's demo catalog (templates.meta), not in
-- the site config, so this rewrites those two templates' meta from the code
-- (packages/store-sections/src/templates/{koora,sabaha}/), guarded so a row
-- an admin has touched (a draft, or the old photo gone) is left alone.
--
-- Idempotent: once applied the old photo id is gone, so the guards match nothing.

UPDATE templates
SET meta = '{"pageNames":{"home":{"ar":"الرئيسية","en":"Home"},"about":{"ar":"عن كورة شوب","en":"About"},"contact":{"ar":"تواصل","en":"Contact"},"faq":{"ar":"الأسئلة الشائعة","en":"FAQ"}},"demo":{"store":{"name":{"ar":"كورة شوب","en":"Koora Shop"},"description":{"ar":"كور وأطقم وأدوات تمرين للخماسي.","en":"Balls, kits and training gear for five-a-side."}},"categories":[{"id":"demo-kits","name":{"ar":"أطقم الفرق","en":"Team kits"},"image":"https://images.pexels.com/photos/18199559/pexels-photo-18199559.jpeg?auto=compress&cs=tinysrgb&w=900","productCount":2},{"id":"demo-balls","name":{"ar":"كور","en":"Balls"},"image":"https://images.pexels.com/photos/36618476/pexels-photo-36618476.jpeg?auto=compress&cs=tinysrgb&w=900","productCount":3},{"id":"demo-training","name":{"ar":"أدوات تمرين","en":"Training gear"},"image":"https://images.pexels.com/photos/2128220/pexels-photo-2128220.jpeg?auto=compress&cs=tinysrgb&w=900","productCount":3},{"id":"demo-goals","name":{"ar":"جول وشبك","en":"Goals & nets"},"image":"https://images.pexels.com/photos/33537003/pexels-photo-33537003.jpeg?auto=compress&cs=tinysrgb&w=900","productCount":2}],"products":[{"id":"demo-printed-team-kit","title":{"ar":"طقم فريق بالاسم والرقم","en":"Printed Team Kit"},"slug":"printed-team-kit","image":"https://images.pexels.com/photos/18199559/pexels-photo-18199559.jpeg?auto=compress&cs=tinysrgb&w=900","price":650,"compareAtPrice":null,"isFeatured":true,"categoryId":"demo-kits","inStock":true,"createdAt":"2026-10-18T00:00:00.000Z","rating":4.8,"sold90":260,"sold14":52},{"id":"demo-training-bibs","title":{"ar":"طقم بيبات تمرين (١٠ قطع)","en":"Training Bibs (10)"},"slug":"training-bibs","image":"https://images.pexels.com/photos/27915834/pexels-photo-27915834.jpeg?auto=compress&cs=tinysrgb&w=900","price":480,"compareAtPrice":null,"isFeatured":false,"categoryId":"demo-kits","inStock":true,"createdAt":"2026-10-17T00:00:00.000Z","rating":4.7,"sold90":90,"sold14":18},{"id":"demo-match-ball-3","title":{"ar":"كور تمرين م